import hashlib, base64, re, glob, struct, subprocess
salt = bytes.fromhex("518D64A635DED8C1E6B039B1C3E55230")
def nid(name):
    d = hashlib.sha1(name.encode() + salt).digest()[:8]
    return base64.b64encode(struct.pack(">Q", struct.unpack("<Q", d)[0])).decode().rstrip("=").replace("/", "-")
stubs = {}
for f in glob.glob("core/libs/prx/**/*.cpp", recursive=True):
    if "/tests/" in f: continue
    txt = open(f, errors="ignore").read()
    for m in re.finditer(r'(\w+)\s*\([^)]*\)\s*\{\s*NotImplemented_nid_no_patch\(__func__\);\s*return[^;]*;\s*\}\s*APS5_EXPORT\("([^"]+)",\s*(\w+)\)', txt):
        stubs.setdefault(m.group(2), []).append(f.split("/")[3])
print("strict stubs", len(stubs))
names = set()
libs = glob.glob("/usr/lib/x86_64-linux-gnu/libstdc++.so.6*") + glob.glob("/usr/lib/x86_64-linux-gnu/libc.so.6") + glob.glob("/usr/lib/x86_64-linux-gnu/libm.so.6") + glob.glob("/usr/lib/llvm-*/lib/libc++.so.1*") + glob.glob("/usr/lib/llvm-*/lib/libc++abi.so.1*") + glob.glob("/usr/lib/x86_64-linux-gnu/libc++*.so*")
for l in set(libs):
    out = subprocess.run(["nm", "-D", "--defined-only", l], capture_output=True, text=True).stdout
    for line in out.splitlines():
        p = line.split()
        if len(p) >= 3: names.add(p[2].split("@")[0])
print("dict names", len(names))
impl = set()
for f in glob.glob("core/libs/prx/**/*.cpp", recursive=True):
    for m in re.finditer(r'\b(\w+)_nid_postfix\b', open(f, errors="ignore").read()): impl.add(m.group(1))
for n in sorted(names):
    k = nid(n)
    if k in stubs:
        print("MATCH", ",".join(sorted(set(stubs[k]))), k, n, "IMPL_ELSEWHERE" if n in impl else "")
EOF
